bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
target=fb2f26a6a9a7811213891f715ad6c225b5a6f00a
base=d6d490c68b3e44790a90f13b727d425815b865e1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 61
checkout="$(git rev-parse --show-toplevel)"
case "$(git -C "$checkout" remote get-url origin)" in *seigo-gace/create-videobot*) ;; *) exit 62;; esac
git -C "$checkout" fetch --no-tags origin "$target" || exit 63
test "$(git -C "$checkout" rev-parse FETCH_HEAD)" = "$target" || exit 64
git -C "$checkout" cat-file -e "$base^{commit}" || exit 65
root=/home/gace/.local/share/gace-create-videobot/native-sticker-c8c50d420c0b9b5d447a1fc87ef3d9e1ec7aceed
test -f "$root/deploy/compose.videobot.poll.yaml" || exit 66
release="$root/.releases/$target/preview-montage-v1"
test ! -e "$release" || exit 67
mkdir -p "$release/live" "$release/base" "$release/new" "$release/patch"
image="$(docker inspect "$cid" --format '{{.Image}}')"
printf '%s\n' "$image" > "$release/base-image"
old=create-videobot:preview-montage-base-fb2f26a
new=create-videobot:preview-montage-fb2f26a
test -z "$(docker images -q "$new")" || exit 68
docker tag "$image" "$old"
files="src/sales/sampleMedia.mjs src/sales/autoPreview.mjs src/telegram/mediaProcessor.mjs src/telegram/freeAlbum.mjs src/telegram/paidListingPublisher.mjs src/telegram/creatorUi.mjs src/telegram/creatorWizard.mjs src/sales/pgListings.mjs src/sales/pgPostingReceipts.mjs src/runtime/creatorMigrate.mjs"
for f in $files; do
 for d in live base new patch;do mkdir -p "$release/$d/$(dirname "$f")";done
 docker cp "$cid:/opt/videobot/$f" "$release/live/$f" || exit 69
 git -C "$checkout" show "$base:$f" > "$release/base/$f" || exit 70
 git -C "$checkout" show "$target:$f" > "$release/new/$f" || exit 71
 if ! git merge-file -p "$release/live/$f" "$release/base/$f" "$release/new/$f" > "$release/patch/$f";then
  echo "MONTAGE_LIVE_MERGE_CONFLICT=$f";exit 72
 fi
done
mkdir -p "$release/patch/sql"
git -C "$checkout" show "$target:sql/023_video_preview_montage.sql" > "$release/patch/sql/023_video_preview_montage.sql"
{ printf 'FROM %s\nUSER root\n' "$old"; for f in $files sql/023_video_preview_montage.sql; do printf 'COPY --chown=node:node patch/%s /opt/videobot/%s\n' "$f" "$f";done;echo 'USER node'; } > "$release/Dockerfile"
docker build --pull=false --network none -t "$new" "$release" >/dev/null || exit 73
for f in $files;do docker run --rm --network none --entrypoint node "$new" --check "/opt/videobot/$f" || exit 74;done
docker run --rm --network none -i --entrypoint node "$new" --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import {mkdtemp,rm,stat} from 'node:fs/promises';
import {join} from 'node:path';
import {tmpdir} from 'node:os';
import {execFile} from 'node:child_process';
import {promisify} from 'node:util';
import {prepareMissingPreviewAssets} from '/opt/videobot/src/sales/autoPreview.mjs';
import {buildFreeAlbumRequest} from '/opt/videobot/src/telegram/freeAlbum.mjs';
const dir=await mkdtemp(join(tmpdir(),'montage-verify-'));
const run=promisify(execFile);
try{
 const source=join(dir,'source.mp4');
 await run('ffmpeg',['-hide_banner','-loglevel','error','-f','lavfi','-i','testsrc2=size=96x64:rate=10','-f','lavfi','-i','sine=frequency=440:sample_rate=48000','-t','80','-c:v','libx264','-threads','1','-pix_fmt','yuv420p','-c:a','aac',source],{timeout:120000});
 const r=await prepareMissingPreviewAssets({sourcePath:source,thumbnailOutputPath:join(dir,'first.jpg'),secondThumbnailOutputPath:join(dir,'second.jpg'),sampleOutputPath:join(dir,'sample.mp4')});
 assert.ok(Math.abs(r.sample.durationSeconds-60)<0.15);
 assert.notEqual(r.thumbnail.path,r.secondThumbnail.path);
 for(const p of [r.thumbnail.path,r.secondThumbnail.path,r.sample.path])assert.ok((await stat(p)).size>0);
 const {stdout}=await run('ffprobe',['-v','error','-show_entries','stream=codec_type,codec_name','-of','json',r.sample.path]);
 const streams=JSON.parse(stdout).streams;assert.ok(streams.some(x=>x.codec_type==='video'&&x.codec_name==='h264'));assert.ok(streams.some(x=>x.codec_type==='audio'&&x.codec_name==='aac'));
 const album=buildFreeAlbumRequest({chatId:1,thumbnailFileId:'photo001',secondThumbnailFileId:'photo002',sampleFileId:'sample001'});
 assert.deepEqual(album.media.map(x=>x.type),['photo','photo','video']);
 assert.equal(album.media[2].supports_streaming,true);
 console.log('MONTAGE_TWO_PHOTOS_ONE_SAMPLE_REAL_FFMPEG=PASS');
}finally{await rm(dir,{recursive:true,force:true});}
NODE
test "$(docker inspect "$cid" --format '{{.Image}}')" = "$image" || exit 75
echo MONTAGE_STAGE_ONLY=PASS
